"use client";

import { AnimatePresence, LayoutGroup, motion, useReducedMotion } from "motion/react";
import { useEffect, useId, useRef, useState } from "react";

import { BlockFrame } from "../parts/block-frame";
import { SearchField } from "./search-field";
import { CATEGORIES, INITIAL_CONNECTED, TOOLS, type Tool } from "./integrations/data";
import { FilterTabs } from "./integrations/filter-tabs";
import { type ConnectionState, ToolRow } from "./integrations/tool-row";

const CONNECT_DELAY = 1100;

/**
 * A directory of tools a clinic can connect: search, filter by connected or
 * by category with live counts, and connect a tool in place. Rows reflow when
 * the filter changes.
 */
export function Integrations({ className }: { className?: string }) {
  const [states, setStates] = useState<Record<string, ConnectionState>>(() =>
    Object.fromEntries(TOOLS.map((tool) => [tool.id, INITIAL_CONNECTED.includes(tool.id) ? "on" : "off"])),
  );
  const [filter, setFilter] = useState("all");
  const [query, setQuery] = useState("");
  const [announcement, setAnnouncement] = useState("");
  const timers = useRef(new Set<ReturnType<typeof setTimeout>>());
  const reduceMotion = useReducedMotion();
  const titleId = useId();

  useEffect(() => {
    const pending = timers.current;
    return () => pending.forEach(clearTimeout);
  }, []);

  const connected = (tool: Tool) => states[tool.id] === "on";
  const needle = query.trim().toLowerCase();
  const searched = TOOLS.filter(
    (tool) => needle === "" || `${tool.name} ${tool.category} ${tool.line}`.toLowerCase().includes(needle),
  );
  const options = [
    { value: "all", label: "All", count: searched.length },
    { value: "connected", label: "Connected", count: searched.filter(connected).length },
    ...CATEGORIES.map((category) => ({
      value: category,
      label: category,
      count: searched.filter((tool) => tool.category === category).length,
    })),
  ];
  const shown = searched.filter((tool) =>
    filter === "all" ? true : filter === "connected" ? connected(tool) : tool.category === filter,
  );

  const connect = (tool: Tool) => {
    setStates((current) => ({ ...current, [tool.id]: "connecting" }));
    setAnnouncement(`Connecting ${tool.name}.`);
    const timer = setTimeout(() => {
      timers.current.delete(timer);
      setStates((current) => ({ ...current, [tool.id]: "on" }));
      setAnnouncement(`${tool.name} connected.`);
    }, CONNECT_DELAY);
    timers.current.add(timer);
  };

  const disconnect = (tool: Tool) => {
    setStates((current) => ({ ...current, [tool.id]: "off" }));
    setAnnouncement(`${tool.name} disconnected.`);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-col gap-3 border-b border-border px-5 py-4">
        <div className="flex flex-wrap items-end justify-between gap-x-6 gap-y-3">
          <div className="min-w-0">
            <h2 id={titleId} className="text-base font-semibold">
              Integrations
            </h2>
            <p className="text-sm text-muted-foreground">Connect the tools your clinics already use. Bookings flow to them on their own.</p>
          </div>
          <SearchField label="Search tools" value={query} onChange={setQuery} className="w-full @lg:w-64" />
        </div>
        <FilterTabs aria-label="Show tools" options={options} value={filter} onValueChange={setFilter} />
      </header>

      <LayoutGroup>
        <ul aria-label={`${shown.length} tools`} className="flex min-h-48 flex-col py-2">
          <AnimatePresence initial={false} mode="popLayout">
            {shown.map((tool) => (
              <motion.li
                key={tool.id}
                layout={!reduceMotion}
                initial={reduceMotion ? false : { opacity: 0, scale: 0.98 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.98, transition: { duration: reduceMotion ? 0 : 0.12 } }}
                transition={{ duration: reduceMotion ? 0 : 0.24, ease: [0.22, 1, 0.36, 1] }}
              >
                <ToolRow
                  tool={tool}
                  state={states[tool.id] ?? "off"}
                  onConnect={() => connect(tool)}
                  onDisconnect={() => disconnect(tool)}
                />
              </motion.li>
            ))}
          </AnimatePresence>
          {shown.length === 0 ? (
            <li className="px-5 py-10 text-center text-sm text-muted-foreground">
              {needle ? `No tool here matches “${query.trim()}”.` : "Nothing connected yet."}
            </li>
          ) : null}
        </ul>
      </LayoutGroup>
      <p role="status" className="sr-only">
        {announcement}
      </p>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

