/** Props for a search box with a leading magnifier. */
export interface SearchFieldProps {
  value: string;
  onChange: (value: string) => void;
  /** Names the box for screen readers and fills the empty box. */
  label: string;
  /** Sets the typed text in the code face, for searching key names. */
  code?: boolean;
  className?: string;
}

/** A search box: a magnifier beside a search input. */
export function SearchField({ value, onChange, label, code = false, className }: SearchFieldProps) {
  const id = useId();
  return (
    <div className={cn("flex items-center gap-2", code && "font-mono", className)}>
      <SearchIcon aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
      <label htmlFor={id} className="sr-only">
        {label}
      </label>
      <Input
        id={id}
        type="search"
        value={value}
        onChange={(event) => onChange(event.target.value)}
        placeholder={label}
        autoComplete="off"
        spellCheck={false}
        className="flex-1"
      />
    </div>
  );
}

