"use client";

import { motion, useReducedMotion } from "motion/react";
import { type KeyboardEvent, useId, useRef } from "react";

import { NumberTicker } from "@/components/motion/number-ticker";
import { Button } from "@/components/ui/button";

/** One filter option with how many tools it holds. */
export interface FilterOption {
  value: string;
  label: string;
  count: number;
}

/** Props for the filter row. */
export interface FilterTabsProps {
  options: FilterOption[];
  value: string;
  onValueChange: (value: string) => void;
  "aria-label": string;
}

/**
 * A row of filter options with live counts and a pill that slides to the
 * choice. It is a radio group: Tab reaches the checked option, arrows, Home
 * and End move and select. The row scrolls sideways on a narrow screen.
 */
export function FilterTabs({ options, value, onValueChange, "aria-label": label }: FilterTabsProps) {
  const reduceMotion = useReducedMotion();
  const layoutId = useId();
  const refs = useRef(new Map<string, HTMLButtonElement>());

  const onKeyDown = (event: KeyboardEvent) => {
    const index = options.findIndex((option) => option.value === value);
    let next: number;
    if (event.key === "ArrowRight" || event.key === "ArrowDown") next = (index + 1) % options.length;
    else if (event.key === "ArrowLeft" || event.key === "ArrowUp") next = (index - 1 + options.length) % options.length;
    else if (event.key === "Home") next = 0;
    else if (event.key === "End") next = options.length - 1;
    else return;
    event.preventDefault();
    const option = options[next];
    if (!option) return;
    onValueChange(option.value);
    const button = refs.current.get(option.value);
    button?.focus();
    button?.scrollIntoView({ block: "nearest", inline: "nearest" });
  };

  return (
    <div role="radiogroup" aria-label={label} onKeyDown={onKeyDown} className="-mx-1 flex scroll-fade-effect-x scrollbar-none gap-1 overflow-x-auto px-1 py-1">
      {options.map((option) => {
        const checked = option.value === value;
        return (
          <Button
            key={option.value}
            ref={(node) => {
              if (node) refs.current.set(option.value, node);
              else refs.current.delete(option.value);
            }}
            type="button"
            variant={checked ? "ghost" : "ghost"}
            size="sm"
            role="radio"
            aria-checked={checked}
            tabIndex={checked ? 0 : -1}
            onClick={() => onValueChange(option.value)}
            className="relative shrink-0"
          >
            {checked ? (
              <motion.span
                layoutId={layoutId}
                aria-hidden="true"
                transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 520, damping: 46 }}
                className="absolute inset-0 rounded-md border border-border bg-muted"
              />
            ) : null}
            <span className="relative">{option.label}</span>
            <span className="relative text-xs text-muted-foreground tabular-nums">
              <NumberTicker value={option.count} />
            </span>
          </Button>
        );
      })}
    </div>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useRef, useState } from "react";

import { CircleCheckIcon } from "@/components/blocks/parts/icons";
import { Switch } from "@/components/motion/switch";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

import { LoaderIcon, SettingsIcon } from "../icons";
import type { Tool } from "./data";
import { ToolMark } from "./tool-mark";

/** Where one tool's connection stands. */
export type ConnectionState = "off" | "connecting" | "on";

/** Props for one tool in the directory. */
export interface ToolRowProps {
  tool: Tool;
  state: ConnectionState;
  onConnect: () => void;
  onDisconnect: () => void;
}

const SWAP = { initial: { opacity: 0, y: 4 }, animate: { opacity: 1, y: 0 }, exit: { opacity: 0, y: -4 } };

/**
 * One tool: its mark, name, category and line, then Connect, or a Connected
 * badge with Configure. Configure opens a small panel in place.
 */
export function ToolRow({ tool, state, onConnect, onDisconnect }: ToolRowProps) {
  const [configuring, setConfiguring] = useState(false);
  const [twoWay, setTwoWay] = useState(true);
  const reduceMotion = useReducedMotion();
  const panelId = useId();
  const switchId = useId();
  // The Connect button leaves the page when the tool connects, so focus moves on to Configure.
  const focusNext = useRef(false);
  const swap = reduceMotion ? { initial: false as const } : SWAP;

  return (
    <div className="group relative px-3 py-1">
      <span
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-2 inset-y-0.5 rounded-xl bg-muted opacity-0 motion-safe:transition-opacity group-hover:opacity-60"
      />
      <div className="relative flex items-center gap-3 px-2 py-2.5">
        <ToolMark tool={tool} />
        <div className="flex min-w-0 flex-1 flex-col">
          <h3 className="flex flex-wrap items-baseline gap-x-2 text-sm font-medium">
            {tool.name}
            <span className="text-xs font-normal text-muted-foreground">{tool.category}</span>
          </h3>
          <p className="text-sm text-muted-foreground">{tool.line}</p>
        </div>
        <div className="flex shrink-0 items-center justify-end gap-2 @lg:w-56">
          <AnimatePresence mode="wait" initial={false}>
            {state === "on" ? (
              <motion.div key="on" {...swap} transition={{ duration: 0.18 }} className="flex items-center gap-2">
                <Badge variant="secondary" className="hidden @md:inline-flex">
                  <CircleCheckIcon aria-hidden="true" />
                  Connected
                </Badge>
                <Button
                  ref={(node) => {
                    if (node && focusNext.current) {
                      focusNext.current = false;
                      node.focus();
                    }
                  }}
                  variant="outline"
                  size="sm"
                  aria-expanded={configuring}
                  aria-controls={panelId}
                  aria-label={`Configure ${tool.name}, connected`}
                  onClick={() => setConfiguring(!configuring)}
                >
                  <SettingsIcon aria-hidden="true" className="size-4" />
                  <span className="hidden @md:inline">Configure</span>
                </Button>
              </motion.div>
            ) : (
              <motion.div key="off" {...swap} transition={{ duration: 0.18 }}>
                <Button
                  size="sm"
                  onClick={(event) => {
                    if (state === "connecting") return;
                    focusNext.current = event.currentTarget === document.activeElement;
                    onConnect();
                  }}
                  aria-disabled={state === "connecting"}
                  aria-label={state === "connecting" ? `Connecting ${tool.name}` : `Connect ${tool.name}`}
                >
                  {state === "connecting" ? (
                    <>
                      <LoaderIcon aria-hidden="true" className="size-4 motion-safe:animate-spin" />
                      Connecting
                    </>
                  ) : (
                    "Connect"
                  )}
                </Button>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>
      <AnimatePresence initial={false}>
        {state === "on" && configuring ? (
          <motion.div
            id={panelId}
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: reduceMotion ? 0 : 0.2 }}
            className="relative overflow-hidden"
          >
            <div className="flex flex-wrap items-center justify-between gap-3 pt-1 pb-3 pl-15 pr-2">
              <label htmlFor={switchId} className="flex items-center gap-3 text-sm">
                <Switch id={switchId} checked={twoWay} onCheckedChange={setTwoWay} />
                Sync changes both ways
              </label>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => {
                  setConfiguring(false);
                  onDisconnect();
                }}
              >
                Disconnect
              </Button>
            </div>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}

